        layer.el.addEventListener('keydown', rec.keyHandler);
        layer.el.setAttribute('aria-label', settings.label || state.label || '菜单');
        layer.el.tabIndex = -1;
        layer.el.setAttribute('data-menu-depth', String(rec.depth));
