      state.checked = Boolean(state.checked);
      state.disabled = Boolean(state.disabled);
      state.required = Boolean(state.required);

      var base = uid('nui-switch');
      var labelId = base + '-label';
      var hintId = base + '-hint';
      var errorId = base + '-error';
