    if (short) {
      var expanded = short[1].toLowerCase().split('').map(function (character) {
        return character + character;
      }).join('');
      return '#' + expanded;
    }
    var full = /^#([0-9a-fA-F]{6})$/.exec(value);
    return full ? '#' + full[1].toLowerCase() : null;
