    var finishCaptionHint = typeof config.finishCaptionHint === 'function' ? config.finishCaptionHint : null;
    var getCause = typeof config.getCause === 'function' ? config.getCause : null;

    var destroyed = false;
    var currentState = null;
    var slots = [];
